css:
@font-face { font-family: 'JPSerif'; src: url('file://__FONT_ROOT__/YuGothR.ttc'); }
@font-face { font-family: 'JPSans'; src: url('file://__FONT_ROOT__/msgothic.ttc'); }
html, body { margin: 0; padding: 0; background: #fff; color: #000; }
.page { width: 794px; height: 1123px; position: relative; overflow: hidden;
        font-family: 'JPSerif'; font-size: 14px; }
.abs { position: absolute; }
.h { writing-mode: horizontal-tb; line-height: 1.75; }
.v { writing-mode: vertical-rl; line-height: 1.85; text-align: justify; }
.v p { margin: 0; text-indent: 1em; }
.box { border: 1px solid #000; padding: 22px 26px; box-sizing: border-box; }
.sig { writing-mode: vertical-rl; text-align: end; }
.h p { margin: 0; }
rt { font-size: 50%; }
.tcy { text-combine-upright: all; }
.label { font-family: 'JPSans'; font-size: 15px; }
.center { text-align: center; }
